/* بيانات باب rsifat: تُحمَّل عند أول فتح للقسم */
window.RSIFAT = {"ch":[{"id":"ahd","t":"الصدق والوفاء بالعهد والثبات","d":"الآيات التي وصفت رجالاً صدقوا ما عاهدوا الله عليه، وقالوا كلمة الحق في موطن الخوف، وكان منهم مؤمنون بين ظهراني المشركين."},{"id":"masjid","t":"رجال المساجد والذكر والطهارة","d":"الآيات التي وصفت رجالاً يسبّحون الله في المساجد لا تلهيهم التجارة، ويحبون التطهّر، ويأتون البيت من كل فجّ."},{"id":"nush","t":"رجال النصيحة والصدع بالحق","d":"الآيات التي ذكرت رجالاً جاؤوا يسعون إلى النصح، وصدعوا بكلمة الحق عند أهل القوة، وأن الرسل رجال من البشر يوحى إليهم."},{"id":"mas","t":"الرجال والجماعة: قوامة وكسب وشهادة ونصرة","d":"الآيات التي جاء فيها لفظ «الرجال» في سياق مسؤوليتهم في الجماعة: القيام بالنفقة والحماية، ونصيبهم مما اكتسبوا، والإشهاد، ونصرة المستضعفين."},{"id":"fityan","t":"الفتية الذين آمنوا بربهم","d":"الآيات التي ذكرت فتية آمنوا بربهم فزادهم الله هدى: أصحاب الكهف، وفتى سمعه قومه يذكر آلهتهم، وهو إبراهيم عليه السلام."},{"id":"amthal","t":"أمثال ضربها الله برجلين وبرجل","d":"الأمثال التي ضربها الله بالرجال: صاحب الجنتين وصاحبه، والأبكم ومن يأمر بالعدل، والرجل المشترك بين شركاء متشاكسين، ونفي القلبين في جوف رجل."},{"id":"akhira","t":"رجال الأعراف ورجال الاستعاذة بالجن","d":"الآيات التي ذكرت رجال الأعراف ونداءهم رجالاً يعرفونهم بسيماهم، وقول الجن إن رجالاً من الإنس كانوا يعوذون برجال من الجن."}],"tp":[{"id":"sadaqu","ch":"ahd","t":"«رجال صدقوا ما عاهدوا الله عليه»","e":"وصف المؤمنين الذين صدقوا عهدهم: منهم من قضى نحبه ومنهم من ينتظر وما بدّلوا تبديلاً.","ay":[[33,23,24]],"q":[{"bk":"saadi","s":33,"ay":23,"x":"ولما ذكر أنَّ المنافقين عاهدوا الله لا يولُّون الأدبار ونقضوا ذلك العهد؛ ذكر وفاء المؤمنين به، فقال:{من المؤمنينَ رجالٌ صَدَقوا ما عاهَدوا الله عليه}؛ أي: وَفَّوْا به وأتموُّه وأكملوه، فبذلوا مُهَجَهُم في مرضاتِهِ، وسبَّلوا نفوسهم في طاعته. {فمنهم من قضى نحبَهُ}؛ أي: إرادته ومطلوبَه وما عليه من الحقِّ، فقُتل في سبيل الله أو مات مؤدياً لحقِّه لم ينقصْه شيئاً، {ومنهم مَن ينتظِرُ}: تكميل ما عليه؛ فهو شارعٌ في قضاء ما عليه ووفاء نحبِهِ ولما يُكْمِلْه، وهو في رجاء تكميله ساعٍ في ذلك مجدٌّ، {وما بَدَّلوا تبديلاً}: كما بدَّل غيرُهم، بل لم يزالوا على العهد، لا يلوون ولا يتغيرون؛ فهؤلاء الرجال على الحقيقة، ومن عداهم فصُورُهم صورُ رجال وأما الصفاتُ؛ فقد قَصُرَتْ عن صفاتِ الرجال.","w":"السعدي","en":"Al-Sa'di: After mentioning that the hypocrites pledged to Allah not to turn their backs and then broke it, He mentions the believers' fulfilment: \"men who were true to what they pledged to Allah\" means they fulfilled it, completed it, gave their lives for His pleasure and put themselves at the service of obeying Him. \"Some of them fulfilled their vow\" means what they intended and what was due from them: they were killed in Allah's cause or died having discharged what was due without shortfall; \"and some still wait\" to complete what remains on them, already at work on it and earnestly striving; \"and they never changed\" as others changed, but never ceased to keep the pledge, never wavering or altering. These are the men in truth; as for others, their forms are the forms of men, but their qualities fall short of the qualities of men."},{"bk":"ibnkathir","s":33,"ay":23,"x":"لمَّا ذَكَرَ عَنِ الْمُنَافِقِينَ أَنَّهُمْ نَقَضُوا الْعَهْدَ الَّذِي كَانُوا عَاهِدُوا اللَّهَ عَلَيْهِ لَا يُوَلُّونَ الْأَدْبَارَ، وَصَفَ الْمُؤْمِنِينَ بِأَنَّهُمُ اسْتَمَرُّوا عَلَى الْعَهْدِ وَالْمِيثَاقِ وَ ﴿صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ﴾ ، قَالَ بَعْضُهُمْ: أَجْلَهُ.","w":"ابن كثير","en":"Ibn Kathir: After mentioning that the hypocrites broke the pledge they had made to Allah not to turn their backs, He described the believers as having kept to the covenant and pledge, \"true to what they pledged to Allah; some of them fulfilled their vow\" — some said: meaning their appointed time."},{"bk":"qurtubi","s":33,"ay":23,"x":"وَقَالَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا فِي قَوْلِهِ تَعَالَى \"مِنَ الْمُؤْمِنِينَ رِجالٌ صَدَقُوا مَا عاهَدُوا اللَّهَ عَلَيْهِ\" الْآيَةَ: مِنْهُمْ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ثَبَتَ مَعَ رَسُولِ اللَّهِ ﷺ حَتَّى أُصِيبَتْ يَدُهُ، فَقَالَ النَّبِيُّ ﷺ: (أَوْجَبَ طَلْحَةُ الْجَنَّةَ).","w":"القرطبي","en":"Al-Qurtubi: A'isha, may Allah be pleased with her, said about the verse \"Among the believers are men true to what they pledged to Allah\": among them was Talha ibn Ubaydillah, who stood firm with the Messenger of Allah, peace be upon him, until his hand was struck; the Prophet said: \"Talha has made Paradise his due.\""}]},{"id":"rajulan","ch":"ahd","t":"«قال رجلان من الذين يخافون الله أنعم الله عليهما»","e":"رجلان من الذين يخافون الله أنعم الله عليهما يحثان قومهما على دخول الباب والتوكل على الله.","ay":[[5,23,23]],"q":[{"bk":"saadi","s":5,"ay":23,"x":"{قال رجلانِ من الذين يخافونَ} الله تعالى؛ مشجعَيْنِ لقومهم، منهضَيْنِ لهم على قتال عدوهم واحتلال بلادهم {أنعم الله عليهما}: بالتوفيق وكلمة الحقِّ في هذا الموطن المحتاج إلى مثل كلامهم، وأنعم عليهم بالصبر واليقين، {ادخُلوا عليهم البابَ، فإذا دَخَلۡتُموه فإنَّكم غالبون}؛ أي: ليس بينكم وبين نصرِكم عليهم إلاَّ أن تجزموا عليهم وتدخلوا عليهم الباب؛ فإذا دخلتُموه عليهم؛ فإنهم سينهزمون. ثم أمراهم بعدة هي أقوى العدد، فقالا:{وعلى الله فتوكَّلوا إنۡ كنتم مؤمنين}: فإنَّ في التوكُّل على الله، وخصوصاً في هذا الموطن، تيسيراً للأمر ونصراً على الأعداء.","w":"السعدي","en":"Al-Sa'di: \"Two men of those who feared\" Allah said, encouraging their people and urging them to fight their enemy and take their land; Allah had favoured them with success and with the word of truth in a place that needed such words, and with patience and certainty: \"Enter upon them through the gate; once you enter it, you will surely prevail\" — nothing stands between you and victory over them except your firm resolve and entering the gate; once you enter, they will be routed. Then they told them of the strongest provision: \"And put your trust in Allah, if you are believers\" — for trust in Allah, especially at such a moment, makes the matter easy and brings victory over enemies."},{"bk":"ibnkathir","s":5,"ay":23,"x":"وَقَوْلُهُ: ﴿قَالَ رَجُلانِ مِنَ الَّذِينَ يَخَافُونَ أَنْعَمَ اللَّهُ عَلَيْهِمَا﴾ أَيْ: فَلَمَّا نَكَلَ بَنُو إِسْرَائِيلَ عَنْ طَاعَةِ اللَّهِ وَمُتَابَعَةِ رَسُولِ اللَّهِ مُوسَى، عَلَيْهِ السَّلَامُ، حَرَّضَهُمْ رَجُلَانِ لِلَّهِ عَلَيْهِمَا نِعْمَةٌ عَظِيمَةٌ، وَهُمَا مِمَّنْ يَخَافُ أَمْرَ اللَّهِ وَيَخْشَى عِقَابَهُ.","w":"ابن كثير","en":"Ibn Kathir: \"Two men of those who feared said, whom Allah had favoured\": when the Children of Israel refused to obey Allah and follow Allah's messenger Musa, peace be upon him, two men upon whom Allah had bestowed a great favour urged them on; they were of those who fear Allah's command and dread His punishment."}]},{"id":"kitman","ch":"ahd","t":"رجال مؤمنون بين ظهراني المشركين","e":"ذكر رجال ونساء مؤمنين بين أظهر المشركين لا يعلمهم المسلمون، وما ذُكر في الآية من سبب كفّ القتال.","ay":[[48,25,25]],"q":[{"bk":"saadi","s":48,"ay":25,"x":"وكلُّ هذه أمورٌ موجبةٌ وداعيةٌ إلى قتالهم، ولكن ثمَّ مانعٌ، وهو وجودُ رجال ونساء من أهل الإيمان بين أظهر المشركين، وليسوا بمتميِّزين بمحلةٍ أو مكانٍ يمكن أن لا ينالَهم أذى؛ فلولا هؤلاء الرجال المؤمنون والنساء المؤمنات الذين لا يعلمهم المسلمون {أن تطؤوهم}؛ أي: خشية أن تطؤوهم، {فتصيبَكم منهم مَعَرَّةٌ بغير علم}: والمعرَّةُ ما يدخل تحت قتالهم من نيلِهِم بالأذى والمكروه، وفائدةٌ أخريَّةٌ، وهو أنه لِيُدْخِلَ {في رحمته مَن يشاءُ}: فَيَمُنَّ عليهم بالإيمان بعد الكفر، وبالهدى بعد الضلال، فيمنعكم من قتالهم لهذا السبب، {لو تَزَيَّلوا}؛ أي: لو زالوا من بين أظهرهم، {لعذَّبۡنا الذين كَفَروا منهم عذاباً أليماً}: بأن نبيحَ لكم قتالَهم، ونأذنَ فيه، وننصرَكم عليهم.","w":"السعدي","en":"Al-Sa'di: All these are matters that call for fighting them, but there is an obstacle: the presence of believing men and women among the polytheists, not set apart in a quarter or place where they could be spared harm. Were it not for these believing men and believing women whom the Muslims did not know, lest you trample them and some blame befall you from them without knowledge — \"ma'arra\" being the harm and hurt that comes with fighting them — and there is a further benefit: that He may admit into His mercy whom He wills, granting them faith after disbelief and guidance after misguidance; so He holds you back from fighting them for this reason. \"Had they been separate\", that is, had they gone away from among them, \"We would have punished those among them who disbelieved with a painful punishment\" — by permitting you to fight them, allowing it, and giving you victory over them."},{"bk":"ibnkathir","s":48,"ay":25,"x":"وَقَوْلُهُ: ﴿وَلَوْلا رِجَالٌ مُؤْمِنُونَ وَنِسَاءٌ مُؤْمِنَاتٌ﴾ أَيْ: بَيْنَ أَظْهُرِهِمْ مِمَّنْ يَكْتُمُ إِيمَانَهُ وَيُخْفِيهِ مِنْهُمْ خِيفَةً عَلَى أَنْفُسِهِمْ مِنْ قَوْمِهِمْ، لَكُنَّا سَلَّطناكم عَلَيْهِمْ فَقَتَلْتُمُوهُمْ وَأَبَدْتُمْ خَضْرَاءَهُمْ، وَلَكِنْ بَيْنَ أَفْنَائِهِمْ مِنَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ أَقْوَامٌ لَا تَعْرِفُونَهُمْ حَالَةَ الْقَتْلِ؛ وَلِهَذَا قَالَ: ﴿لَمْ تَعْلَمُوهُمْ أَنْ تَطَئُوهُمْ فَتُصِيبَكُمْ مِنْهُمْ مَعَرَّةٌ﴾ أَيْ: إِثْمٌ وَغَرَامَةٌ ﴿بِغَيْرِ عِلْمٍ لِيُدْخِلَ اللَّهُ فِي رَحْمَتِهِ مَنْ يَشَاءُ﴾ أَيْ: يُؤَخِّرُ عُقُوبَتَهُمْ لِيُخَلِّصَ مِنْ بَيْنِ أَظْهُرِهِمُ الْمُؤْمِنِينَ، وَلِيَرْجِعَ كَثِيرٌ مِنْهُمْ إِلَى الْإِسْلَامِ.","w":"ابن كثير","en":"Ibn Kathir: \"Were it not for believing men and believing women\" among them who conceal and hide their faith out of fear for themselves from their people, We would have given you power over them and you would have killed them and wiped out their greenery; but among their families are believing men and women whom you cannot tell apart in the moment of killing. Hence He said: \"whom you did not know, lest you trample them and some blame befall you from them\" — that is, sin and liability — \"without knowledge, that Allah may admit into His mercy whom He wills\" — that is, He delays their punishment so as to extricate the believers from among them, and so that many of them return to Islam."}]},{"id":"tulhihim","ch":"masjid","t":"«رجال لا تلهيهم تجارة ولا بيع عن ذكر الله»","e":"وصف الرجال في المساجد بالتسبيح غدواً وآصالاً، وأن التجارة والبيع لا يشغلانهم عن الذكر والصلاة والزكاة.","ay":[[24,36,37]],"q":[{"bk":"saadi","s":24,"ay":37,"x":"ثم مدح تعالى عُمَّارها بالعبادة، فقال:{يُسَبِّحُ له}: إخلاصاً {بالغدوِّ}: أول النهار {والآصالِ}: آخره {رجالٌ}: خصَّ هذين الوقتين لِشَرَفِهما ولتيسُّر السير فيهما إلى الله وسهولتِهِ، ويدخل في ذلك التسبيح في الصلاة وغيرها، ولهذا شُرِعَتْ أذكارُ الصباح والمساء وأورادُهما عند الصباح والمساء؛ أي: يسبِّح فيها لله رجالٌ، وأيُّ رجال؟! ليسوا ممَّن يؤثِرُ على ربِّه دنيا ذات لذاتٍ ولا تجارةٍ ومكاسبَ مشغلة عنه. {لا تُلهيهم تجارةٌ}: وهذا يَشْمَلُ كلَّ تكسُّب يُقصد به العِوَضُ، فيكون قوله:{ولا بَيۡعٌ}: من باب عطف الخاصِّ على العامِّ؛ لكَثرة الاشتغال بالبيع على غيره؛ فهؤلاء الرجال وإن اتَّجروا وباعوا واشْتَرَوا؛ فإنَّ ذلك لا محذور فيه، لكنَّه لا تلهيهم تلك بأن يقدِّموها ويؤثِروها على {ذِكۡر الله وإقام الصَّلاةِ وإيتاءِ الزكاة}: بل جعلوا طاعةَ الله وعبادتَه غايةَ مرادِهم ونهايةَ مقصدِهم …","w":"السعدي","en":"Al-Sa'di: Then He praised those who populate the mosques with worship: \"He is glorified therein, sincerely, in the mornings and evenings, by men\" — the two times are singled out for their honour and for how easy travelling to Allah is in them; this includes glorification in prayer and outside it, which is why morning and evening adhkar were legislated. That is, men glorify Allah in them — and what men! They are not the kind who prefer a life of pleasures over their Lord, nor trade and earnings that keep them from Him. \"Neither trade distracts them\" — this covers every earning sought for a return — \"nor sale\", which is a case of the specific after the general, because people are so often occupied with selling; so these men may trade, sell and buy and there is no blame in that, but those things do not distract them by being put ahead of \"the remembrance of Allah, establishing prayer and giving zakat\"; rather they make obedience and worship of Allah their utmost aim and final goal …"},{"bk":"ibnkathir","s":24,"ay":37,"x":"فَقَوْلُهُ: ﴿رِجَال﴾ فِيهِ إِشْعَارٌ بِهِمَمِهِمُ السَّامِيَةِ، وَنِيَّاتِهِمْ وَعَزَائِمِهِمُ الْعَالِيَةِ، الَّتِي بِهَا صَارُوا عُمَّارا لِلْمَسَاجِدِ، الَّتِي هِيَ بُيُوتُ اللَّهِ فِي أَرْضِهِ، وَمَوَاطِنُ عِبَادَتِهِ وَشُكْرِهِ، وَتَوْحِيدِهِ وَتَنْزِيهِهِ، كَمَا قَالَ تَعَالَى: ﴿مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ﴾ [الْأَحْزَابِ: ٢٣] .","w":"ابن كثير","en":"Ibn Kathir: His word \"men\" carries a sense of their lofty aspirations, intentions and high resolves, by which they became the builders of the mosques, which are Allah's houses on His earth and places of His worship, thanks, oneness and glorification, as He said: \"Among the believers are men true to what they pledged to Allah\" [al-Ahzab 23]."},{"bk":"qurtubi","s":24,"ay":37,"x":"قَالَ سَالِمٌ: جَازَ عَبْدُ اللَّهِ بْنُ عُمَرَ بِالسُّوقِ وَقَدْ أَغْلَقُوا حَوَانِيتَهُمْ وَقَامُوا لِيُصَلُّوا فِي جَمَاعَةٍ فَقَالَ: فِيهِمْ نَزَلَتْ: \"رِجالٌ لَا تُلْهِيهِمْ تِجارَةٌ وَلا بَيْعٌ\" الْآيَةَ.","w":"القرطبي","en":"Al-Qurtubi: Salim said: Abdullah ibn Umar passed by the market when they had closed their shops and stood to pray in congregation, and he said: \"It was about them that it was revealed: 'Men whom neither trade nor sale distracts'.\""}]},{"id":"taharah","ch":"masjid","t":"«فيه رجال يحبون أن يتطهروا»","e":"ذكر الرجال في مسجد قباء الذين يحبون أن يتطهروا، ومحبة الله للمطّهرين.","ay":[[9,108,108]],"q":[{"bk":"saadi","s":9,"ay":108,"x":"وسألهم النبيُّ - صلى الله عليه وسلم - بعدما نزلت هذه الآية في مدحهم عن طهارتهم؟ فأخبروه أنَّهم يُتْبِعون الحجارة الماء، فحمدهم على صنيعهم.{والله يحبُّ المطَّهِّرين}: الطهارة المعنوية كالتنزُّه من الشرك والأخلاق الرذيلة، والطهارة الحسيَّة كإزالة الأنجاس ورفع الأحداث.","w":"السعدي","en":"Al-Sa'di: After this verse was revealed in their praise, the Prophet, peace be upon him, asked them about their purification. They told him they follow stones with water, and he praised them for what they did. \"And Allah loves those who purify themselves\": inward purity, such as keeping clear of shirk and base character, and outward purity, such as removing impurities and lifting ritual states of impurity."},{"bk":"qurtubi","s":9,"ay":108,"x":"حَدِيثُ أَبِي هُرَيْرَةَ قَالَ: نَزَلَتْ هَذِهِ الْآيَةُ فِي أَهْلِ قُبَاءٍ \"فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ\" قَالَ: كَانُوا يَسْتَنْجُونَ بِالْمَاءِ فَنَزَلَتْ فِيهِمْ هَذِهِ الْآيَةُ.","w":"القرطبي","en":"Al-Qurtubi: The evidence for that is the hadith of Abu Hurayra, who said: This verse was revealed about the people of Quba: \"In it are men who love to purify themselves, and Allah loves those who purify themselves.\" He said: they used to clean themselves with water, so this verse was revealed about them."}]},{"id":"hajj","ch":"masjid","t":"«يأتوك رجالاً وعلى كل ضامر»","e":"نداء إبراهيم بالحج ومجيء الناس رجالاً مشاة وركباناً من كل فجّ عميق.","ay":[[22,27,27]],"q":[{"bk":"saadi","s":22,"ay":27,"x":"أي: مشاة على أرجلهم من الشوق، {وعلى كلِّ ضامرٍ}؛ أي: ناقة ضامرٍ تقطع المهامةَ والمفاوِزَ، وتواصِل السير حتى تأتي إلى أشرف الأماكن، {من كلِّ فجٍّ عميقٍ}؛ أي: من كلِّ بلدٍ بعيدٍ.","w":"السعدي","en":"Al-Sa'di: \"On foot\" — walking on their feet out of longing; \"and on every lean camel\" — a lean she-camel that crosses deserts and wastes and keeps travelling until it reaches the noblest of places; \"from every distant mountain pass\" — from every faraway land."},{"bk":"qurtubi","s":22,"ay":27,"x":"وَعَدَهُ إِجَابَةَ النَّاسِ إِلَى حَجِّ الْبَيْتِ مَا بَيْنَ رَاجِلٍ وَرَاكِبٍ، وَإِنَّمَا قَالَ \"يَأْتُوكَ\" وَإِنْ كَانُوا يَأْتُونَ الْكَعْبَةَ لِأَنَّ الْمُنَادِيَ إِبْرَاهِيمُ، فَمَنْ أَتَى الْكَعْبَةَ حَاجًّا فَكَأَنَّمَا أَتَى إِبْرَاهِيمَ، لِأَنَّهُ أَجَابَ نِدَاءَهُ، وَفِيهِ تشريف إبراهيم.","w":"القرطبي","en":"Al-Qurtubi: \"They will come to you on foot and on every lean camel\": He promised him that people would answer the call to the pilgrimage of the House, whether on foot or riding. He said \"they will come to you\" although they come to the Kaaba, because the caller was Ibrahim: whoever comes to the Kaaba as a pilgrim has as if come to Ibrahim, because he answered his call, and in this is an honour for Ibrahim."}]},{"id":"yasin","ch":"nush","t":"«وجاء من أقصى المدينة رجل يسعى» في سورة يس","e":"رجل جاء من أقصى المدينة يسعى فنصح قومه باتباع المرسلين.","ay":[[36,20,21]],"q":[{"bk":"saadi","s":36,"ay":20,"x":"{وجاء من أقصى المدينةِ رجلٌ يسعى}: حرصاً على نُصْح قومِهِ حين سمعَ ما دَعَتْ إليه الرسل وآمنَ به وعلم ما ردَّ به قومُه عليهم، فقال لهم:{يا قوم اتَّبِعوا المرسلينَ}: فأمَرَهُم باتِّباعهم، ونَصَحَهم على ذلك، وشهد لهم بالرسالة.","w":"السعدي","en":"Al-Sa'di: \"And from the farthest part of the city there came a man running\": out of eagerness to advise his people when he heard what the messengers called to, believed in it, and learned how his people had answered them. He said to them: \"O my people, follow the messengers\": he commanded them to follow them, advised them to do so, and testified for them that they were messengers."},{"bk":"ibnkathir","s":36,"ay":20,"x":"قَالَ ابْنُ إِسْحَاقَ -فِيمَا بَلَغَهُ عَنِ ابْنِ عَبَّاسٍ وَكَعْبِ الْأَحْبَارِ وَوَهْبِ بْنِ مُنَبِّهٍ-: إِنَّ أَهْلَ الْقَرْيَةِ هَمّوا بِقَتْلِ رُسُلِهِمْ فَجَاءَهُمْ رَجُلٌ مِنْ أَقْصَى الْمَدِينَةِ يَسْعَى، أَيْ: لِيَنْصُرَهُمْ مِنْ قَوْمِهِ -قَالُوا: وَهُوَ حَبِيبٌ، وَكَانَ يَعْمَلُ الْجَرِيرَ -وَهُوَ الْحِبَالُ-وَكَانَ رَجُلًا سَقِيمًا قَدْ أَسْرَعَ فِيهِ الْجُذَامُ، وَكَانَ كَثِيرَ الصَّدَقَةِ، يَتَصَدَّقُ بِنِصْفِ كَسْبِهِ، مُسْتَقِيمَ النَّظْرَةِ.","w":"ابن كثير","en":"Ibn Kathir: Ibn Ishaq, from what reached him from Ibn Abbas, Ka'b al-Ahbar and Wahb ibn Munabbih, said: The people of the town resolved to kill their messengers, so a man came from the farthest part of the city running, to support them against his people — they said: he was Habib; he used to make rope, was a sick man in whom leprosy had spread, very charitable, giving half of his earnings in charity, and upright in his outlook."}]},{"id":"qasas20","ch":"nush","t":"«وجاء رجل من أقصى المدينة يسعى» في سورة القصص","e":"رجل جاء من أقصى المدينة يسعى إلى موسى عليه السلام فأخبره بائتمار الملأ به ونصحه بالخروج.","ay":[[28,20,20]],"q":[{"bk":"saadi","s":28,"ay":20,"x":"وشاع الخبرُ بما جرى من موسى في هاتين القضيَّتين حتى تراوَدَ ملأُ فرعونَ وفرعونُ على قتلِهِ، وتشاوروا على ذلك، فقيَّض الله ذلك الرجلَ الناصحَ، وبادرهم إلى الإخبار لموسى بما اجتمع عليه رأي ملئهم، فقال:{وجاء رجلٌ من أقصى المدينة يسعى}؛ أي: ركضاً على قدميه من نُصْحِهِ لموسى وخوفِهِ أن يوقِعوا به قبلَ أن يشعر، فقال:{يا موسى إنَّ الملأ يأتَمِرونَ}؛ أي: يتشاورون فيك؛ {لِيَقۡتُلوك فاخۡرُجۡ}: عن المدينة {إنِّي لك من الناصحين}: فامتثل نُصحه.","w":"السعدي","en":"Al-Sa'di: The news of what Musa had done in those two incidents spread until Pharaoh's chiefs and Pharaoh himself conferred and consulted about killing him. Allah sent that advising man, who hurried to tell Musa what their council had agreed upon: \"And from the farthest part of the city there came a man running\" — hurrying on his feet out of concern for Musa and fear that they would seize him before he knew — and said: \"O Musa, the chiefs are conspiring against you\" — that is, consulting about you — \"to kill you, so leave\" — the city — \"I am to you one of the sincere advisers\"; and Musa accepted his advice."},{"bk":"ibnkathir","s":28,"ay":20,"x":"قَالَ تَعَالَى: ﴿وَجَاءَ رَجُلٌ﴾ وَصَفَهُ بالرّجُولية لِأَنَّهُ خَالَفَ الطَّرِيقَ، فَسَلَكَ طَرِيقًا أَقْرَبَ مِنْ طَرِيقِ الَّذِينَ بُعثوا وَرَاءَهُ، فَسَبَقَ إِلَى مُوسَى، فَقَالَ لَهُ: يَا مُوسَى ﴿إِنَّ الْمَلأ يَأْتَمِرُونَ بِكَ﴾ أَيْ: يَتَشَاوَرُونَ فِيكَ ﴿لِيَقْتُلُوكَ فَاخْرُجْ﴾ أَيْ: مِنَ الْبَلَدِ ﴿إِنِّي لَكَ مِنَ النَّاصِحِينَ﴾ .","w":"ابن كثير","en":"Ibn Kathir: The Most High said: \"And there came a man\" — He described him with manhood (rujuliyya) because he took a different road, a shorter way than those sent after Musa, and reached him first and said: \"O Musa, the chiefs are conspiring against you\" — consulting about you — \"to kill you, so leave\" — the town — \"I am to you one of the sincere advisers.\""}]},{"id":"mumin","ch":"nush","t":"«وقال رجل مؤمن من آل فرعون يكتم إيمانه»","e":"رجل مؤمن من آل فرعون يكتم إيمانه ثم ينكر على قومه عزمهم على قتل موسى.","ay":[[40,28,29]],"q":[{"bk":"saadi","s":40,"ay":28,"x":"ومن جملة الأسباب هذا الرجل المؤمن الذي من آل فرعون من بيت المملكةِ، لا بدَّ أن يكونَ له كلمةٌ مسموعةٌ، وخصوصاً إذا كان يظهِرُ موافقتَهم ويكتُمُ إيمانه؛ فإنهم يراعونَه في الغالب ما لا يراعونَه لو خالفهم في الظاهر؛ كما منع الله رسولَه محمداً - صلى الله عليه وسلم - بعمه أبي طالب من قريش؛ حيث كان أبو طالب كبيراً عندهم موافقاً لهم على دينهم، ولو كان مسلماً؛ لم يحصلْ منه ذلك المنع، فقال ذلك الرجل المؤمن الموفَّق العاقل الحازم مقبِّحاً فعل قومه وشناعة ما عزموا عليه:{أتَقۡتُلونَ رجلاً أن يقولَ ربِّيَ اللهُ}؛ أي: كيف تستحلُّون قتلَه وهذا ذنبُه وجرمُه أَنَّه يقولَ ربِّيَ الله، ولم يكن أيضاً قولاً مجرَّداً عن البيناتِ، ولهذا قال:{وقد جاءكم بالبيِّناتِ من ربِّكم} …","w":"السعدي","en":"Al-Sa'di: Among the means was this believing man of Pharaoh's family, from the house of the kingdom, who must have had a word that was heard, especially as he showed agreement with them while hiding his faith; for they usually give such a person consideration they would not give had he openly opposed them — just as Allah protected His Messenger Muhammad through his uncle Abu Talib among Quraysh, who was a leader among them and shared their religion; had he been a Muslim, that protection would not have come from him. So that believing man, guided, sensible and resolute, condemning what his people did and the ugliness of what they resolved, said: \"Would you kill a man because he says: My Lord is Allah?\" — how can you think it lawful to kill him when his only fault is that he says my Lord is Allah, and not as a bare claim without proofs, hence: \"while he has brought you clear proofs from your Lord\" …"},{"bk":"ibnkathir","s":40,"ay":28,"x":"وَقَدْ كَانَ هَذَا الرجلُ يَكْتُمُ إِيمَانَهُ عَنْ قَوْمِهِ الْقِبْطِ، فَلَمْ يَظْهَرْ إِلَّا هَذَا الْيَوْمَ حِينَ قَالَ فِرْعَوْنُ: ﴿ذَرُونِي أَقْتُلْ مُوسَى﴾ ، فَأَخَذَتِ الرَّجُلَ غَضْبَةٌ لِلَّهِ عَزَّ وَجَلَّ، وَ\"أَفْضَلُ الْجِهَادِ كَلِمَةُ عَدْلٍ عِنْدَ سُلْطَانٍ جَائِرٍ\"، كَمَا ثَبَتَ بِذَلِكَ الْحَدِيثُ، وَلَا أَعْظَمَ مِنْ هَذِهِ الْكَلِمَةِ عِنْدَ فِرْعَوْنَ وَهِيَ قَوْلُهُ: ﴿أَتَقْتُلُونَ رَجُلا أَنْ يَقُولَ رَبِّيَ اللَّهُ﴾ [أَيْ: لِأَجْلِ أَنْ يَقُولَ رَبِّي اللَّهُ] …","w":"ابن كثير","en":"Ibn Kathir: This man had been hiding his faith from his people, the Copts, and it only appeared that day, when Pharaoh said: \"Let me kill Musa\"; so anger for Allah seized the man, and \"the best jihad is a word of justice before a tyrannical ruler\", as the hadith has established, and there is no greater such word before Pharaoh than his words: \"Would you kill a man because he says: My Lord is Allah?\" [that is, because he says: My Lord is Allah] …"}]},{"id":"rusul","ch":"nush","t":"«وما أرسلنا من قبلك إلا رجالاً نوحي إليهم»","e":"أن الله ما أرسل من قبل النبي صلى الله عليه وسلم إلا رجالاً يوحى إليهم من أهل القرى.","ay":[[12,109,109],[21,7,7]],"q":[{"bk":"saadi","s":12,"ay":109,"x":"ثم قال تعالى: {وما أرسلنا من قبلِكَ إلاَّ رجالاً}؛ أي: لم نرسل ملائكةً ولا غيرهم من أصناف الخلق؛ فلأيِّ شيءٍ يَسْتَغْرِبُ قومك رسالتك، ويزعُمون أنه ليس لك عليهم فضلٌ، فلك فيمَنْ قبلك من المرسلين أسوةٌ حسنةٌ.","w":"السعدي","en":"Al-Sa'di: Then He said: \"We sent before you none but men\": We did not send angels or any other kind of creation; so why should your people find your message strange and claim that you have no merit over them? In the messengers before you there is a fine example for you."},{"bk":"ibnkathir","s":21,"ay":7,"x":"يَقُولُ تَعَالَى رادِّا عَلَى مَنْ أَنْكَرَ بِعْثَةَ الرُّسُلِ مِنَ الْبَشَرِ: ﴿وَمَا أَرْسَلْنَا قَبْلَكَ إِلا رِجَالا يُوحَى إِلَيْهِمْ﴾ أَيْ: جَمِيعُ الرُّسُلِ الَّذِينَ تَقَدَّمُوا كَانُوا رِجَالًا مِنَ الْبَشَرِ، لَمْ يَكُنْ فِيهِمْ أَحَدٌ مِنَ الْمَلَائِكَةِ، كَمَا قَالَ فِي الْآيَةِ الْأُخْرَى: ﴿وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ إِلا رِجَالا يُوحَى إِلَيْهِمْ مِنْ أَهْلِ الْقُرَى﴾ [يُوسُفَ: ١٠٩] ، وَقَالَ تَعَالَى: ﴿قُلْ مَا كُنْتُ بِدْعًا مِنَ الرُّسُلِ﴾ [الْأَحْقَافِ:٩] ، وَقَالَ تَعَالَى حِكَايَةً عَمَّنْ تَقَدَّمَ مِنَ الْأُمَمِ أَنَّهُمْ أَنْكَرُوا ذَلِكَ فَقَالُوا: ﴿أَبَشَرٌ يَهْدُونَنَا﴾ [التَّغَابُنِ:٦] ؛ وَلِهَذَا قَالَ تَعَالَى: ﴿فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ﴾ أَيِ:اسْأَلُوا أَهْلَ الْعِلْمِ مِنَ الْأُمَمِ كَالْيَهُودِ وَالنَّصَارَى وَسَائِرِ الطَّوَائِفِ: هَلْ كَانَ الرُّسُلُ الَّذِينَ أَتَوْهُمْ بَشَرًا أَوْ مَلَائِكَةً؟","w":"ابن كثير","en":"Ibn Kathir: The Most High answers those who denied that messengers be sent from among mankind: \"We sent before you only men to whom revelation was given\", meaning all the messengers who came before were men from mankind, not one of them an angel, as He said in the other verse: \"We sent not before you except men to whom We revealed, from the people of the towns\" [Yusuf 109]; and He said: \"Say: I am not an innovation among the messengers\" [al-Ahqaf 9]; and He related of earlier nations that they denied this, saying: \"Shall mortals guide us?\" [al-Taghabun 6]; hence He said: \"So ask the people of the reminder if you do not know\", that is: ask the people of knowledge among the nations, such as the Jews, the Christians and other groups: were the messengers who came to them mortals or angels?"}]},{"id":"qawwamun","ch":"mas","t":"«الرجال قوامون على النساء»","e":"قوامة الرجال على النساء وسببها المذكور في الآية: التفضيل والإنفاق.","ay":[[4,34,34]],"q":[{"bk":"saadi","s":4,"ay":34,"x":"يخبر تعالى أنَّ {الرجال قوامون على النساء}؛ أي: قوَّامون عليهنَّ بإلزامهنَّ بحقوق الله تعالى من المحافظة على فرائضه وكفِّهِنَّ عن المفاسد، والرجال عليهم أن يُلْزِموهنَّ بذلك، وقوَّامون عليهنَّ أيضاً بالإنفاق عليهنَّ والكسوة والمسكن.","w":"السعدي","en":"Al-Sa'di: He informs that \"men are in charge of women\": in charge of them by holding them to Allah's rights, safeguarding His obligations and restraining them from wrongdoing — and men must hold them to that — and in charge of them also by spending on them and providing clothing and housing."},{"bk":"qurtubi","s":4,"ay":34,"x":"أَيْ يَقُومُونَ بِالنَّفَقَةِ عَلَيْهِنَّ وَالذَّبِّ عَنْهُنَّ، وَأَيْضًا فَإِنَّ فِيهِمُ الْحُكَّامَ وَالْأُمَرَاءَ وَمَنْ يَغْزُو، وَلَيْسَ ذَلِكَ فِي النِّسَاءِ.","w":"القرطبي","en":"Al-Qurtubi: That is, they are responsible for spending on them and defending them; and among them are the rulers, the commanders and those who go out to fight, which is not so among women."}]},{"id":"nasib","ch":"mas","t":"«للرجال نصيب مما اكتسبوا»","e":"نصيب الرجال مما اكتسبوا، والنهي عن تمني ما فضّل الله به بعضهم على بعض، ونصيبهم مما ترك الوالدان والأقربون.","ay":[[4,32,32],[4,7,7]],"q":[{"bk":"saadi","s":4,"ay":32,"x":"ينهى تعالى المؤمنين عن أن يتمنَّى بعضُهم ما فضَّل الله به غيره من الأمور الممكنة وغير الممكنة؛ فلا تتمنَّى النساءُ خصائص الرجال التي بها فضَّلهم على النساء، ولا صاحب الفقر والنقص حالة الغنيِّ والكامل تمنياً مجرداً؛ لأنَّ هذا هو الحسد بعينه؛ تمني نعمة الله على غيرك أن تكونَ لك ويُسْلَبَ إياها، ولأنه يقتضي السَّخَطَ على قدر الله، والإخلاد إلى الكسل، والأماني الباطلة التي لا يقترن بها عمل ولا كسب، وإنما المحمود أمران: أن يسعى العبدُ على حسب قدرته بما ينفعه من مصالحه الدينيَّة والدنيويَّة، ويسألَ الله تعالى من فضلِهِ؛ فلا يتَّكل على نفسه ولا على غير ربِّه، ولهذا قال تعالى:{للرجال نصيبٌ مما اكتسبوا}؛ أي: من أعمالهم المنتجة للمطلوب.","w":"السعدي","en":"Al-Sa'di: He forbids the believers to wish for what Allah has favoured others with, whether possible or not: women should not wish for the characteristics of men by which He favoured them over women, nor should the poor and deficient wish for the state of the rich and complete in a bare wish; for this is envy itself — wishing that the blessing of Allah upon another be yours and be taken from him — and it leads to resentment of Allah's decree, to settling into idleness and to vain wishes accompanied by no work or earning. What is praiseworthy is two things: that the servant strive according to his ability for what benefits him in his religious and worldly interests, and ask Allah of His bounty, relying neither on himself nor on anyone but his Lord. Hence the Most High said: \"For men is a share of what they earned\" — that is, of their works that produce what is sought."},{"bk":"qurtubi","s":4,"ay":32,"x":"الثَّالِثَةُ- قَوْلُهُ تَعَالَى: ﴿لِلرِّجالِ نَصِيبٌ مِمَّا اكْتَسَبُوا﴾ يُرِيدُ مِنَ الثَّوَابِ والعقاب (وَلِلنِّساءِ) كذلك، قاله قَتَادَةُ.","w":"القرطبي","en":"Al-Qurtubi: \"For men is a share of what they have earned\": he means reward and punishment, \"and for women\" likewise; said Qatada."}]},{"id":"shahada","ch":"mas","t":"«واستشهدوا شهيدين من رجالكم»","e":"الأمر بالإشهاد بشهيدين من الرجال عند المداينة.","ay":[[2,282,282]],"q":[{"bk":"ibnkathir","s":2,"ay":282,"x":"وَقَوْلُهُ ﴿وَاسْتَشْهِدُوا شَهِيدَيْنِ مِنْ رِجَالِكُم﴾ أمْرٌ بِالْإِشْهَادِ مَعَ الْكِتَابَةِ لِزِيَادَةِ التَّوْثِقَةِ …","w":"ابن كثير","en":"Ibn Kathir: His words \"And call to witness two witnesses from among your men\" are a command to have witnesses as well as writing, for added assurance …"},{"bk":"saadi","s":2,"ay":282,"x":"ومنها: الإرشاد إلى إشهاد رجلين عدلين فإن لم يمكن أو تعذر أو تعسر فرجل وامرأتان، وذلك شامل لجميع المعاملات، بيوع الإدارة وبيوع الديون وتوابعها من الشروط والوثائق وغيرها.","w":"السعدي","en":"Al-Sa'di: Among the lessons of the verse: guidance to have two upright men as witnesses; if that is not possible, or is hard or difficult, then one man and two women; and this covers all transactions — sales on the spot, sales on credit with their conditions and documents, and other matters."}]},{"id":"mustad","ch":"mas","t":"المستضعفون من الرجال والنساء والولدان","e":"حثّ المؤمنين على استنقاذ المستضعفين من الرجال والنساء والولدان الذين يدعون الله أن يخرجهم من القرية الظالم أهلها.","ay":[[4,75,75]],"q":[{"bk":"saadi","s":4,"ay":75,"x":"هذا حثٌّ من الله لعبادِهِ المؤمنين وتهييجٌ لهم على القتال في سبيله، وأنَّ ذلك قد تعيَّن عليهم وتوجَّه اللوم العظيم عليهم بتركِهِ، فقال:{وما لكم لا تقاتِلون في سبيل اللهِ}؛ والحالُ أنَّ المستضعفين من الرجال والنساءِ والولدان الذين لا يستطيعونَ حيلةً ولا يهتدونَ سبيلاً، ومع هذا فقد نالهم أعظم الظُّلم من أعدائهم؛ فهم يدعون الله أن يخرِجَهم من هذه القريةِ الظالم أهلُها لأنفسهم بالكفرِ والشركِ، وللمؤمنينَ بالأذى والصدِّ عن سبيل الله، ومنعِهِم من الدعوة لدينهم والهجرة، ويدعونَ الله أن يجعلَ لهم وليًّا ونصيراً يستنقِذُهم من هذه القرية الظالم أهلُها، فصار جهادُكم على هذا الوجه من باب القتال والذَّبِّ عن عَيْلاتِكم وأولادِكم ومحارِمِكم …","w":"السعدي","en":"Al-Sa'di: This is an urging from Allah to His believing servants and a stirring to fight in His way, which has become binding on them, with great blame for leaving it: \"Why should you not fight in the cause of Allah\" when the oppressed among men, women and children, who have no means and find no way, have suffered the gravest wrong from their enemies, and pray to Allah to bring them out of this town whose people are wrongdoers to themselves by disbelief and shirk, and to the believers by harm and by barring them from Allah's path and from calling to their religion and migrating; they ask Allah to give them a protector and helper to rescue them from this town of wrongdoers; so your fighting on this basis becomes defending your families, children and dependants …"},{"bk":"ibnkathir","s":4,"ay":75,"x":"يُحَرِّضُ تَعَالَى عِبَادَهُ الْمُؤْمِنِينَ عَلَى الْجِهَادِ فِي سَبِيلِهِ وَعَلَى السَّعْيِ فِي اسْتِنْقَاذِ الْمُسْتَضْعَفِينَ بِمَكَّةَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالصِّبْيَانِ الْمُتَبَرِّمِينَ بِالْمَقَامِ بِهَا؛ وَلِهَذَا قَالَ تَعَالَى: ﴿الَّذِينَ يَقُولُونَ رَبَّنَا أَخْرِجْنَا مِنْ هَذِهِ الْقَرْيَةِ﴾ يَعْنِي: مَكَّةَ، كَقَوْلِهِ تَعَالَى: ﴿وَكَأَيِّنْ مِنْ قَرْيَةٍ هِيَ أَشَدُّ قُوَّةً مِنْ قَرْيَتِكَ الَّتِي أَخْرَجَتْكَ﴾ [مُحَمَّدٍ: ١٣] .","w":"ابن كثير","en":"Ibn Kathir: The Most High urges His believing servants to fight in His cause and to strive to rescue the oppressed in Mecca — men, women and children who were weary of staying there; hence He said: \"Who say: Our Lord, bring us out of this town\" — meaning Mecca — as in His words: \"How many a town was stronger than your town that expelled you\" [Muhammad 13]."}]},{"id":"kahf13","ch":"fityan","t":"«إنهم فتية آمنوا بربهم وزدناهم هدى»","e":"وصف أصحاب الكهف بأنهم فتية آمنوا بربهم وزادهم الله هدى.","ay":[[18,13,14]],"q":[{"bk":"saadi","s":18,"ay":13,"x":"وهذا من جموع القلَّة، يدلُّ ذلك على أنَّهم دون العشرة، آمنوا بالله وحدَه لا شريك له من دون قومهم، فشكر اللهُ لهم إيمانَهم، فزادهم هدىً؛ أي: بسبب أصل اهتدائهم إلى الإيمان زادهم الله من الهدى الذي هو العلم النافع والعمل الصالح؛ كما قال تعالى:{ويزيدُ الله الذين اهتَدَوۡا هدىً}.","w":"السعدي","en":"Al-Sa'di: \"They were youths who believed in their Lord\": this is a plural of paucity, indicating they were fewer than ten; they believed in Allah alone, with no partner, apart from their people; so Allah thanked them for their faith and increased them in guidance — that is, because of their initial guidance to faith Allah increased them in the guidance that is beneficial knowledge and righteous deeds, as He said: \"And Allah increases those who are guided in guidance.\""},{"bk":"ibnkathir","s":18,"ay":13,"x":"مِنْ هَاهُنَا شَرَعَ فِي بَسْطِ الْقِصَّةِ وَشَرْحِهَا، فَذَكَرَ تَعَالَى أَنَّهُمْ فِتْيَةٌ -وَهُمُ الشَّبَابُ-وَهُمْ أَقْبَلُ لِلْحَقِّ، وَأَهْدَى لِلسَّبِيلِ مِنَ الشُّيُوخِ، الَّذِينَ قَدْ عَتَوْا وعَسَوا فِي دِينِ الْبَاطِلِ؛ وَلِهَذَا كَانَ أَكْثَرُ الْمُسْتَجِيبِينَ لِلَّهِ وَلِرَسُولِهِ ﷺ شَبَابًا.","w":"ابن كثير","en":"Ibn Kathir: From here He begins to spread out the story and explain it; He mentioned that they were youths — young men — who are more receptive to truth and better guided on the path than the elders who have grown hard and obstinate in the religion of falsehood; hence most of those who answered Allah and His Messenger, peace be upon him, were young people."},{"bk":"qurtubi","s":18,"ay":13,"x":"وَقَوْلُهُ تَعَالَى: ﴿إِنَّهُمْ فِتْيَةٌ﴾ أَيْ شَبَابٌ وَأَحْدَاثٌ حَكَمَ لَهُمْ بِالْفُتُوَّةِ حِينَ آمَنُوا بِلَا وَاسِطَةٍ، كَذَلِكَ قَالَ أَهْلُ اللِّسَانِ: رَأْسُ الْفُتُوَّةِ الْإِيمَانُ.","w":"القرطبي","en":"Al-Qurtubi: His words \"They were youths\": young men and youths; they were given the status of manly virtue (futuwwa) when they believed without an intermediary; thus say the people of language: the head of futuwwa is faith."}]},{"id":"kahf16","ch":"fityan","t":"«فأووا إلى الكهف ينشر لكم ربكم من رحمته»","e":"اعتزال الفتية قومهم ومعبوداتهم ولجوؤهم إلى الكهف، وحذرهم من ظهور قومهم عليهم.","ay":[[18,16,16],[18,19,20]],"q":[{"bk":"saadi","s":18,"ay":16,"x":"أي: انضمُّوا إليه واختفوا فيه، {يَنۡشُرۡ لكم ربُّكم من رحمتِهِ ويهيِّئۡ لكم من أمرِكُم مِرۡفَقاً}: وفيما تقدَّم أخبر أنهم دَعَوْه بقولهم: {ربَّنا آتنا من لَدُنۡكَ رحمةً وهَيِّئ لنا من أمرنا رَشَداً}؛ فجمعوا بين التبرِّي من حولهم وقوَّتهم والالتجاء إلى الله في صلاح أمرهم ودعائه بذلك، وبين الثقة بالله أنه سيفعل ذلك، لا جَرَمَ أنَّ الله نَشَرَ لهم من رحمتِهِ وهيَّأ لهم من أمرهم مِرْفَقاً؛ فحفظ أديانهم وأبدانهم، وجعلهم من آياته على خلقه، ونشر لهم من الثناء الحسن ما هو من رحمته بهم، ويسَّر لهم كلَّ سبب، حتَّى المحلَّ الذي ناموا فيه كان على غايةِ ما يمكنُ من الصيانة …","w":"السعدي","en":"Al-Sa'di: \"Take refuge in the cave\" — that is, join it and hide in it — \"Your Lord will spread His mercy over you and prepare for you a comfortable way out of your affair\": earlier He said they had called on Him saying \"Our Lord, grant us mercy from Yourself and prepare for us right guidance in our affair\"; so they combined disowning their own power and strength, turning to Allah for the soundness of their affair and calling on Him for it, with trust in Allah that He would do so; so it was no surprise that Allah spread His mercy over them and prepared for them a comfortable way: He protected their religion and their bodies, made them one of His signs for His creation, spread good repute for them as a mercy to them, and made every means easy for them, even the place where they slept was as safe as could be …"},{"bk":"ibnkathir","s":18,"ay":16,"x":"فَلَمَّا وَقَعَ عَزْمُهُمْ عَلَى الذَّهَابِ وَالْهَرَبِ مِنْ قَوْمِهِمْ، وَاخْتَارَ اللَّهُ تَعَالَى لَهُمْ ذَلِكَ، وَأَخْبَرَ عَنْهُمْ بِذَلِكَ فِي قَوْلِهِ: ﴿وَإِذِ اعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلا اللَّهَ﴾ أَيْ: وَإِذَا فَارَقْتُمُوهُمْ وَخَالَفْتُمُوهُمْ بِأَدْيَانِكُمْ فِي عِبَادَتِهِمْ غَيْرَ اللَّهِ، فَفَارِقُوهُمْ أَيْضًا بِأَبْدَانِكُمْ ﴿فَأْوُوا إِلَى الْكَهْفِ يَنْشُرْ لَكُمْ رَبُّكُمْ مِنْ رَحْمَتِهِ﴾ أَيْ: يَبْسُطْ عَلَيْكُمْ رَحْمَةً يَسْتُرُكُمْ بِهَا مِنْ قَوْمِكُمْ ﴿وَيُهَيِّئْ لَكُمْ مِنْ أَمْرِكُمْ﴾ [أَيِ] الَّذِي أَنْتُمْ فِيهِ، ﴿مِرفَقًا﴾ أَيْ: أَمْرًا تَرْتَفِقُونَ بِهِ. فَعِنْدَ ذَلِكَ خَرَجُوا هُرابًا إِلَى الْكَهْفِ، فَأَوَوْا إِلَيْهِ، فَفَقَدَهُمْ قَوْمُهُمْ مِنْ بَيْنِ أَظْهُرِهِمْ، وتَطَلَّبهم الْمَلِكُ فَيُقَالُ: إِنَّهُ لَمْ يَظْفَرْ بِهِمْ، وعَمَّى اللَّهُ عَلَيْهِ خَبَرَهُمْ.","w":"ابن كثير","en":"Ibn Kathir: When they resolved to leave and flee from their people, and Allah chose that for them and told of it in His words \"And when you have withdrawn from them and from what they worship except Allah\" — that is, when you have parted from them and differed from them in your religion in their worship of others than Allah, then part from them in your bodies too — \"take refuge in the cave; your Lord will spread His mercy over you\" — He will extend a mercy that shelters you from your people — \"and prepare for you in your affair\" — in which you are — \"a comfortable way out\" — something you can benefit from. Then they went out fleeing to the cave and took refuge in it; their people missed them from among them, the king sought them, and it is said he did not find them, for Allah concealed their news from him."},{"bk":"ibnkathir","s":18,"ay":20,"x":"وَقَوْلُهُ ﴿وَلْيَتَلَطَّفْ﴾ أَيْ: فِي خُرُوجِهِ وَذَهَابِهِ، وَشِرَائِهِ وَإِيَابِهِ، يَقُولُونَ: وَلْيَتَخَفَّ كُلَّ مَا يَقْدِرُ عَلَيْهِ ﴿وَلا يُشْعِرَنَّ﴾ أَيْ: وَلَا يُعْلِمَنَّ ﴿بِكُمْ أَحَدًا إِنَّهُمْ إِنْ يَظْهَرُوا عَلَيْكُمْ يَرْجُمُوكُمْ﴾ أَيْ: إِنْ عَلِمُوا بِمَكَانِكُمْ، ﴿يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِي مِلَّتِهِمْ﴾ يَعْنُونَ أَصْحَابَ دَقْيَانُوسَ، يَخَافُونَ مِنْهُمْ أَنْ يَطَّلِعُوا عَلَى مَكَانِهِمْ، فَلَا يَزَالُونَ يُعَذِّبُونَهُمْ بِأَنْوَاعِ الْعَذَابِ إِلَى أَنْ يُعِيدُوهُمْ فِي ملتهم التي هم عليها أو يَمُوتُوا، وَإِنْ واتَوهم عَلَى الْعَوْدِ فِي الدِّينِ فَلَا فَلَاحَ لَكُمْ فِي الدُّنْيَا وَلَا فِي الْآخِرَةِ، وَلِهَذَا قَالَ ﴿وَلَنْ تُفْلِحُوا إِذًا أَبَدًا﴾ .","w":"ابن كثير","en":"Ibn Kathir: His words \"and let him be gentle\": in his going out and coming back, buying and returning; they say: let him take all the care he can \"and let him not make anyone aware of you; if they prevail over you they will stone you\" — that is, if they learn of your place — \"stone you or return you to their creed\" — they mean the people of Daqyanus; they feared they would learn their place and keep torturing them with kinds of torment until they returned them to their creed or they died; and if they conceded to them to return to the religion there would be no success for them in this world or the Hereafter; hence He said: \"and you will never succeed then.\""}]},{"id":"ibrahim","ch":"fityan","t":"«سمعنا فتى يذكرهم يقال له إبراهيم»","e":"قول قوم إبراهيم: سمعنا فتى يذكرهم يقال له إبراهيم، وحلفه على كيد الأصنام.","ay":[[21,57,60]],"q":[{"bk":"saadi","s":21,"ay":60,"x":"{قالوا سَمِعۡنا فتىً يذكُرُهم} ـ أي: يَعيبهم ويذُمُّهم، ومَنْ هذا شأنُهُ لا بدَّ أن يكون هو الذي كسرها، أو أنَّ بعضهم سَمِعَهُ يذكر أنه سيكيدها ـ {يُقال له إبراهيمُ}.","w":"السعدي","en":"Al-Sa'di: \"They said: We heard a youth mention them\" — that is, criticise and disparage them; whoever does so must be the one who broke them, or some of them heard him say he would plot against them — \"called Ibrahim\"."},{"bk":"qurtubi","s":21,"ay":57,"x":"قَوْلُهُ تَعَالَى: ﴿وَتَاللَّهِ لَأَكِيدَنَّ أَصْنامَكُمْ﴾ أَخْبَرَ أَنَّهُ لَمْ يَكْتَفِ بِالْمُحَاجَّةِ بِاللِّسَانِ بَلْ كَسَّرَ أَصْنَامَهُمْ فِعْلَ وَاثِقٍ بِاللَّهِ تَعَالَى، مُوَطِّنٍ نَفْسَهُ عَلَى مُقَاسَاةِ الْمَكْرُوهِ فِي الذَّبِّ عَنِ الدِّينِ.","w":"القرطبي","en":"Al-Qurtubi: His words \"By Allah, I will plot against your idols\": He informed that he was not content with arguing by tongue but broke their idols, acting with trust in Allah, resolved to bear the hardship in defending the religion."},{"bk":"ibnkathir","s":21,"ay":60,"x":"﴿قَالُوا سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُ إِبْرَاهِيمُ﴾ أَيْ: قَالَ مَنْ سَمِعَهُ يَحْلِفُ أَنَّهُ لَيَكِيدَنَّهُمْ: ﴿سَمِعْنَا فَتًى﴾ أَيْ: شَابًّا ﴿يَذْكُرُهُمْ يُقَالُ لَهُ إِبْرَاهِيمُ﴾ قَالَ ابْنُ أَبِي حَاتِمٍ: حَدَّثَنَا مُحَمَّدُ بْنُ عَوْفٍ، حَدَّثَنَا سَعِيدُ بْنُ مَنْصُورٍ، حَدَّثَنَا جَرِيرُ بْنُ عَبْدِ الْحَمِيدِ، عَنْ قَابُوسٍ [عَنْ أَبِيهِ] ، عَنِ ابْنِ عَبَّاسٍ قَالَ: مَا بَعَثَ اللَّهُ نَبِيًّا إِلَّا شَابًّا، وَلَا أُوتِيَ الْعَلَمَ عَالِمٌ إِلَّا وَهُوَ شَابٌّ، وَتَلَا هَذِهِ الْآيَةَ: ﴿قَالُوا سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُ إِبْرَاهِيمُ﴾ .","w":"ابن كثير","en":"Ibn Kathir: \"They said: We heard a youth mention them, called Ibrahim\": that is, the one who heard him swear he would plot against them said: \"we heard a youth\" — a young man — \"mention them, called Ibrahim\". Ibn Abi Hatim related, through his chain, from Ibn Abbas, who said: \"Allah sent no prophet except as a young man, and no scholar was given knowledge except as a young man\", and he recited this verse: \"They said: We heard a youth mention them, called Ibrahim.\""}]},{"id":"jannatayn","ch":"amthal","t":"مثل الرجلين: صاحب الجنتين وصاحبه المؤمن","e":"مثل رجلين لأحدهما جنتان فكفر بنعمة الله واغترّ بماله، ولصاحبه المؤمن الذي ناصحه.","ay":[[18,32,34],[18,39,43]],"q":[{"bk":"saadi","s":18,"ay":32,"x":"يقول تعالى لنبيه - صلى الله عليه وسلم -: اضرِبْ للناس مَثَلَ هذين الرجلين: الشاكر لنعمة الله، والكافر لها، وما صدر من كلٍّ منهما من الأقوال والأفعال، وما حصل بسبب ذلك من العقاب العاجل والآجل والثواب؛ ليعتبروا بحالهما، ويتَّعظوا بما حصل عليهما، وليس معرفة أعيان الرجلين وفي أيِّ زمان أو مكانٍ هما فيه فائدة أو نتيجة؛ فالنتيجة تحصُلُ من قصتهما فقط، والتعرُّض لما سوى ذلك من التكلُّف.","w":"السعدي","en":"Al-Sa'di: The Most High says to His Prophet, peace be upon him: Draw for people the parable of these two men: the one grateful for Allah's blessing and the one ungrateful for it; what each said and did, and what resulted for each of punishment, now and later, or reward, so that they take a lesson from their state and take heed of what befell them; there is no benefit in knowing the identities of the two men or in which time or place they were; the result comes from their story alone, and going beyond it is an affectation."},{"bk":"ibnkathir","s":18,"ay":39,"x":"ثُمَّ قَالَ: ﴿وَلَوْلا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلا بِاللَّهِ إِنْ تَرَنِ أَنَا أَقَلَّ مِنْكَ مَالا وَوَلَدًا﴾ هَذَا تَحْضِيضٌ وَحَثٌّ عَلَى ذَلِكَ، أَيْ: هَلَّا إِذَا أَعْجَبَتْكَ حِينَ دَخَلْتَهَا وَنَظَرْتَ إِلَيْهَا حَمِدْتَ اللَّهَ عَلَى مَا أَنْعَمَ به عليك، وأعطاك من المال والولد مَا لَمْ يُعْطَهُ غَيْرُكَ، وَقُلْتَ: ﴿مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلا بِاللَّهِ﴾ ؛ وَلِهَذَا قَالَ بَعْضَ السَّلَفِ: مَنْ أَعْجَبَهُ شَيْءٌ مِنْ حَالِهِ أَوْ مَالِهِ أَوْ وَلَدِهِ أَوْ مَالِهِ، فَلْيَقُلْ: ﴿مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلا بِاللَّهِ﴾ وَهَذَا مَأْخُوذٌ مِنْ هَذِهِ الْآيَةِ الْكَرِيمَةِ.","w":"ابن كثير","en":"Ibn Kathir: Then He said: \"If only, when you entered your garden, you had said: What Allah wills! There is no power except with Allah. If you see me with less wealth and children than you…\" — this is an urging: why did you not, when it impressed you as you entered and looked at it, praise Allah for what He gave you of wealth and children that He gave no one else, and say \"What Allah wills; there is no power but with Allah\"? Hence some of the early generation said: whoever is impressed by something of his condition, his wealth or his children, let him say: \"What Allah wills; there is no power but with Allah\"; and this is taken from this noble verse."},{"bk":"saadi","s":18,"ay":39,"x":"ففي هذه القصة العظيمة اعتبارٌ بحال الذي أنعم الله عليه نعماً دنيويَّة، فألهتْه عن آخرته، وأطغتْه، وعصى الله فيها، أنَّ مآلها الانقطاع والاضمحلال، وأنَّه وإنْ تمتَّع بها قليلاً؛ فإنَّه يحرمها طويلاً، وأنَّ العبد ينبغي له إذا أعجبه شيءٌ من مالِهِ أو ولدِهِ أن يضيفَ النعمة إلى موليها ومُسْديها، وأن يقولَ: ما شاء اللهُ، لا قوَّة إلاَّ بالله؛ ليكون شاكراً [لله] متسبِّباً لبقاء نعمته عليه؛ لقوله:{ولولا إذۡ دخلتَ جنَّتَك قلتَ ما شاء اللهُ لا قوَّةَ إلاَّ بالله}.","w":"السعدي","en":"Al-Sa'di: In this great story is a lesson in the state of one whom Allah blessed with worldly blessings that distracted him from his Hereafter and made him rebel and disobey Allah in them: that they end in cessation and decay; that though he enjoys them a little, he is deprived of them long; and that when something of his wealth or children impresses a servant he should attribute the blessing to the One who gave it and say \"What Allah wills; there is no power but with Allah\", so as to be thankful [to Allah] and a cause for His blessing to remain on him — because of His words: \"If only, when you entered your garden, you had said: What Allah wills! There is no power except with Allah.\""}]},{"id":"abkam","ch":"amthal","t":"مثل الرجلين: أبكم لا يقدر على شيء ومن يأمر بالعدل","e":"مثل رجلين: أحدهما أبكم لا يقدر على شيء، والآخر يأمر بالعدل وهو على صراط مستقيم.","ay":[[16,75,76]],"q":[{"bk":"saadi","s":16,"ay":76,"x":"والمثل الثاني: مَثَلُ {رجلين أحدُهما أبكمُ}: لا يسمعُ ولا ينطِقُ، و {لا يقدِرُ على شيءٍ}: لا قليل ولا كثير، {وهو كَلٌّ على مولاه}؛ أي: يخدمه مولاه ولا يستطيع هو أن يخدِمَ نفسه؛ فهو ناقصٌ من كلِّ وجه، فهل يَسْتَوي هذا ومَنْ كان {يأمُرُ بالعدل وهو على صراطٍ مستقيم}: فأقوالُهُ عدلٌ وأفعاله مستقيمةٌ؛ فكما أنهما لا يستويان؛ فلا يستوي مَنْ عُبِدَ من دون الله وهو لا يقدِرُ على شيء من مصالحه؛ فلولا قيامُ الله بها؛ لم يستطعْ شيئاً منها، لا يكون كفواً ولا ندًّا لمن لا يقولُ إلاَّ الحقَّ، ولا يفعلُ إلاَّ ما يُحْمَدُ عليه.","w":"السعدي","en":"Al-Sa'di: The second parable: \"two men, one of whom is dumb\", who neither hears nor speaks, \"and who has no power over anything\", neither little nor much, \"and is a burden on his master\", that is, his master serves him while he cannot serve himself; he is deficient in every respect. Is he equal to one who \"commands justice and is on a straight path\", whose words are just and whose deeds are upright? As these two are not equal, so what is worshipped besides Allah, unable to manage any of its own affairs, so that without Allah's maintaining them it could do nothing, can never be a peer or equal to the One who speaks only the truth and does only what is praiseworthy."},{"bk":"qurtubi","s":16,"ay":76,"x":"قَوْلُهُ تَعَالَى: ﴿وَضَرَبَ اللَّهُ مَثَلًا رَجُلَيْنِ أَحَدُهُما أَبْكَمُ﴾ هَذَا مَثَلٌ آخَرُ ضَرَبَهُ اللَّهُ تَعَالَى لِنَفْسِهِ وَلِلْوَثَنِ، فَالْأَبْكَمُ الَّذِي لَا يَقْدِرُ على شي هُوَ الْوَثَنُ، وَالَّذِي يَأْمُرُ بِالْعَدْلِ هُوَ اللَّهُ تَعَالَى، قَالَهُ قَتَادَةُ وَغَيْرُهُ.","w":"القرطبي","en":"Al-Qurtubi: His words \"And Allah gives a parable of two men, one of whom is dumb\": this is another parable Allah gave for Himself and for the idol: the dumb one who has no power over anything is the idol, and the one who commands justice is Allah the Most High; said Qatada and others."}]},{"id":"mutashakis","ch":"amthal","t":"مثل رجل فيه شركاء متشاكسون ورجل سلم لرجل","e":"مثل رجل فيه شركاء متشاكسون ورجل خالص لرجل، وسؤال: هل يستويان مثلاً؟","ay":[[39,29,29]],"q":[{"bk":"saadi","s":39,"ay":29,"x":"فهم كثيرون، وليسوا متَّفقينَ على أمرٍ من الأمور وحالةٍ من الحالات حتى تُمْكِنَ راحتُه، بل هم متشاكسونَ متنازِعون فيه، كلٌّ له مطلبٌ يريد تنفيذَه ويريدُ الآخرُ غيرَه؛ فما تظنُّ حال هذا الرجل مع هؤلاء الشركاء المتشاكسين؟!","w":"السعدي","en":"Al-Sa'di: They are many and do not agree on any matter or state so that he could be at rest; rather they quarrel over him, each with a demand he wants carried out while the other wants something else; so what do you think of this man's state with these quarrelling partners?"},{"bk":"ibnkathir","s":39,"ay":29,"x":"ثُمَّ قَالَ: ﴿ضَرَبَ اللَّهُ مَثَلا رَجُلا فِيهِ شُرَكَاءُ مُتَشَاكِسُونَ﴾ أَيْ: يَتَنَازَعُونَ فِي ذَلِكَ الْعَبْدِ الْمُشْتَرَكِ بَيْنَهُمْ، ﴿وَرَجُلا سَلَمًا لِرَجُلٍ﴾ أَيْ: خَالِصًا لِرَجُلٍ، لَا يَمْلِكُهُ أَحَدٌ غَيْرُهُ، ﴿هَلْ يَسْتَوِيَانِ مَثَلا﴾ أَيْ: لَا يَسْتَوِي هَذَا وَهَذَا.","w":"ابن كثير","en":"Ibn Kathir: Then He said: \"Allah gives a parable of a man in whom are partners quarrelling\" — that is, disputing over that slave shared between them — \"and a man wholly devoted to one man\" — exclusively for one man, owned by no one else — \"are the two equal in comparison?\" — that is, this one and that one are not equal."}]},{"id":"qalbayn","ch":"amthal","t":"«ما جعل الله لرجل من قلبين في جوفه»","e":"نفي الله أن يجعل لرجل قلبين في جوفه، وسبب النزول المنقول.","ay":[[33,4,4]],"q":[{"bk":"saadi","s":33,"ay":4,"x":"يعاتِبُ تعالى عبادَه عن التكلُّم بما لا حقيقةَ له من الأقوال، ولم يجعلْه الله تعالى كما قالوا؛ فإنَّ ذلك القول منكم كذبٌ وزورٌ يترتَّب عليه منكراتٌ من الشرع، وهذه قاعدةٌ عامةٌ في التكلُّم في كلِّ شيء والإخبار بوقوع ووجود ما لَمْ يَجْعَلْه الله تعالى، ولكن خصَّ هذه الأشياء المذكورة لوقوعها وشدة الحاجة إلى بيانها، فقال:{ما جَعَلَ الله لرجل مِن قَلۡبَيۡنِ في جَوۡفِهِ}: هذا لا يوجد؛ فإيَّاكم أن تقولوا عن أحدٍ: إنَّ له قلبينِ في جوفه، فتكونوا كاذبين على الخلقة الإلهية …","w":"السعدي","en":"Al-Sa'di: He rebukes His servants for saying what has no reality, which Allah has not made as they claim; such speech is lies and falsehood that leads to wrongs in the law; this is a general rule on speaking of anything and reporting the occurrence or existence of what Allah has not made; but He singled out these matters because they occurred and the need to explain them was great, and said: \"Allah has not made for any man two hearts within his body\": this does not exist, so beware of saying of anyone that he has two hearts in his body, lest you lie against the divine creation …"},{"bk":"ibnkathir","s":33,"ay":4,"x":"وَقَدْ ذَكَرَ غَيْرُ وَاحِدٍ: أَنَّ هَذِهِ الْآيَةَ نَزَلَتْ فِي رَجُلٍ مِنْ قُرَيْشٍ، كَانَ يُقَالُ لَهُ: \"ذُو الْقَلْبَيْنِ\"، وَأَنَّهُ كَانَ يَزْعُمُ أَنَّ لَهُ قَلْبَيْنِ، كُلٌّ مِنْهُمَا بِعَقْلٍ وَافِرٍ.","w":"ابن كثير","en":"Ibn Kathir: More than one has mentioned that this verse was revealed about a man of Quraysh called \"the man of two hearts\", who claimed he had two hearts, each with ample intellect."}]},{"id":"araf","ch":"akhira","t":"«وعلى الأعراف رجال يعرفون كلاً بسيماهم»","e":"أصحاب الأعراف رجال يعرفون كلاً بسيماهم، ونداؤهم رجالاً يعرفونهم بسيماهم.","ay":[[7,46,49]],"q":[{"bk":"saadi","s":7,"ay":46,"x":"أي: وبين أصحاب الجنة وأصحاب النار حجابٌ يُقال له: الأعراف، لا من الجنة ولا من النار، يشرف على الدارين، وينظُر من عليه حال الفريقين، وعلى هذا الحجاب رجالٌ يعرفونَ كلًّا من أهل الجنة والنار بسيماهم؛ أي: علاماتهم التي بها يُعْرَفون ويُمَيَّزون؛ فإذا نظروا إلى أهل الجنة؛ نادَوْهم:{أن سلامٌ عليكم}؛ أي: يحيُّونهم ويسلِّمون عليهم، وهم إلى الآن لم يدخلوا الجنة، ولكنهم يطمعون في دخولها، ولم يجعل الله الطمع في قلوبهم إلا لما يُريد بهم من كرامته.","w":"السعدي","en":"Al-Sa'di: That is: between the people of Paradise and the people of the Fire is a veil called al-A'raf, neither of Paradise nor of the Fire, overlooking both abodes, from which the state of both groups can be seen; on this veil are men who know each of the people of Paradise and Fire by their marks — the signs by which they are known and told apart; when they look at the people of Paradise they call out \"Peace be upon you\", greeting them, though they have not yet entered Paradise but hope to enter it; and Allah did not place the hope in their hearts except for the honour He intends for them."},{"bk":"saadi","s":7,"ay":48,"x":"ثم ذكر الخصوص بعد العموم، فقال:{ونادى أصحابُ الأعراف رجالاً يعرفونهم بسيماهُم}: وهم من أهل النار، وقد كانوا في الدنيا لهم أبهة وشرفٌ وأموالٌ وأولادٌ، فقال لهم أصحاب الأعراف حين رأوهم منفردين في العذاب بلا ناصرٍ ولا مغيث:{ما أغنى عنكُم جمعُكم}: في الدُّنيا الذي تستدفِعون به المكاره، وتوسلون به إلى مطالبكم في الدُّنيا؛ فاليوم اضمحل ولا أغنى عنكم شيئاً، وكذلك أيُّ شيءٍ نفعكم استكباركم على الحقِّ وعلى ما جاء به وعلى مَن اتبعه؟!","w":"السعدي","en":"Al-Sa'di: Then He mentions the specific after the general: \"And the companions of al-A'raf will call to men whom they know by their marks\" — they are of the people of the Fire; in the world they had pomp, rank, wealth and children; the companions of al-A'raf said to them when they saw them alone in torment without helper or rescuer: \"Of no avail to you was your gathering\" — in the world, by which you warded off harms and reached your goals; today it has vanished and avails you nothing; and likewise, what benefit did your arrogance toward the truth, toward what came with it and toward whoever followed it, bring you?"},{"bk":"ibnkathir","s":7,"ay":48,"x":"يَقُولُ اللَّهُ تَعَالَى مُخْبِرًا عَنْ تَقْرِيعِ أَهْلِ الْأَعْرَافِ لِرِجَالٍ مِنْ صَنَادِيدِ الْمُشْرِكِينَ وَقَادَتِهِمْ، يَعْرِفُونَهُمْ فِي النَّارِ بِسِيمَاهُمْ: ﴿مَا أَغْنَى عَنْكُمْ جَمْعُكُمْ﴾ أَيْ: كَثْرَتُكُمْ، ﴿وَمَا كُنْتُمْ تَسْتَكْبِرُونَ﴾ أَيْ: لَا يَنْفَعُكُمْ كَثْرَتُكُمْ وَلَا جُمُوعُكُمْ مِنْ عَذَابِ اللَّهِ، بَلْ صِرْتُمْ إِلَى مَا صِرْتُمْ فِيهِ مِنَ الْعَذَابِ وَالنَّكَالِ.","w":"ابن كثير","en":"Ibn Kathir: Allah tells of the reproach of the companions of al-A'raf to men from the chiefs of the polytheists and their leaders, whom they recognise in the Fire by their marks: \"Of no avail to you was your gathering\" — that is, your large numbers — \"nor what you used to be arrogant about\" — your numbers and crowds do not save you from Allah's punishment; rather you have come to what you are in of torment and chastisement."}]},{"id":"jinn","ch":"akhira","t":"«يعوذون برجال من الجن فزادوهم رهقاً»","e":"قول الجن إن رجالاً من الإنس كانوا يعوذون برجال من الجن فزادوهم رهقاً.","ay":[[72,6,6]],"q":[{"bk":"qurtubi","s":72,"ay":6,"x":"وَالْمُرَادُ بِهِ مَا كَانُوا يَفْعَلُونَهُ مِنْ قَوْلِ الرَّجُلِ إِذَا نَزَلَ بِوَادٍ: أَعُوذُ بِسَيِّدِ هَذَا الْوَادِي مِنْ شَرِّ سُفَهَاءِ قَوْمِهِ، فَيَبِيتُ فِي جِوَارِهِ حَتَّى يُصْبِحَ، قَالَهُ الْحَسَنُ وَابْنُ زَيْدٍ وَغَيْرُهُمَا.","w":"القرطبي","en":"Al-Qurtubi: The meaning is what they used to do: when a man stopped at a valley he would say: \"I seek refuge with the master of this valley from the evil of the fools of his people\", and he would spend the night in his protection until morning; said al-Hasan, Ibn Zayd and others."},{"bk":"ibnkathir","s":72,"ay":6,"x":"وَقَوْلُهُ: ﴿وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإنْسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا﴾ أَيْ: كُنَّا نَرَى أَنَّ لَنَا فَضْلًا عَلَى الْإِنْسِ؛ لِأَنَّهُمْ كَانُوا يَعُوذُونَ بِنَا، أَيْ: إِذَا نَزَلُوا وَادِيًا أَوْ مَكَانًا مُوحِشًا مِنَ الْبَرَارِي وَغَيْرِهَا كَمَا كَانَ عَادَةُ الْعَرَبِ فِي جَاهِلِيَّتِهَا.","w":"ابن كثير","en":"Ibn Kathir: His words: \"And that there were men among humans who sought refuge with men among the jinn, so they increased them in burden\": that is, we (the jinn) thought we had an advantage over humans because they used to seek refuge with us, when they stopped in a valley or a desolate place in the wilds, as was the custom of the Arabs in their pre-Islamic age."}]}],"ay":{"288":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","499":"لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبٗا مَّفۡرُوضٗا","524":"وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا","526":"ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّٰتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا","567":"وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا","691":"قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ","999":"وَبَيۡنَهُمَا حِجَابٞۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالٞ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ لَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ","1000":"۞ وَإِذَا صُرِفَتۡ أَبۡصَٰرُهُمۡ تِلۡقَآءَ أَصۡحَٰبِ ٱلنَّارِ قَالُواْ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","1001":"وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالٗا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ","1002":"أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُواْ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَيۡكُمۡ وَلَآ أَنتُمۡ تَحۡزَنُونَ","1342":"لَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ","1704":"وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰٓۗ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ٱتَّقَوۡاْۚ أَفَلَا تَعۡقِلُونَ","1975":"۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا مَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا فَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ","1976":"وَضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلَيۡنِ أَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن يَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","2152":"نَّحۡنُ نَقُصُّ عَلَيۡكَ نَبَأَهُم بِٱلۡحَقِّۚ إِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى","2153":"وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُواْ فَقَالُواْ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَن نَّدۡعُوَاْ مِن دُونِهِۦٓ إِلَٰهٗاۖ لَّقَدۡ قُلۡنَآ إِذٗا شَطَطًا","2155":"وَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا ٱللَّهَ فَأۡوُۥٓاْ إِلَى ٱلۡكَهۡفِ يَنشُرۡ لَكُمۡ رَبُّكُم مِّن رَّحۡمَتِهِۦ وَيُهَيِّئۡ لَكُم مِّنۡ أَمۡرِكُم مِّرۡفَقٗا","2158":"وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلٞ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ بِكُمۡ أَحَدًا","2159":"إِنَّهُمۡ إِن يَظۡهَرُواْ عَلَيۡكُمۡ يَرۡجُمُوكُمۡ أَوۡ يُعِيدُوكُمۡ فِي مِلَّتِهِمۡ وَلَن تُفۡلِحُوٓاْ إِذًا أَبَدٗا","2171":"۞ وَٱضۡرِبۡ لَهُم مَّثَلٗا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبٖ وَحَفَفۡنَٰهُمَا بِنَخۡلٖ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعٗا","2172":"كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَيۡـٔٗاۚ وَفَجَّرۡنَا خِلَٰلَهُمَا نَهَرٗا","2173":"وَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا","2178":"وَلَوۡلَآ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالٗا وَوَلَدٗا","2179":"فَعَسَىٰ رَبِّيٓ أَن يُؤۡتِيَنِ خَيۡرٗا مِّن جَنَّتِكَ وَيُرۡسِلَ عَلَيۡهَا حُسۡبَانٗا مِّنَ ٱلسَّمَآءِ فَتُصۡبِحَ صَعِيدٗا زَلَقًا","2180":"أَوۡ يُصۡبِحَ مَآؤُهَا غَوۡرٗا فَلَن تَسۡتَطِيعَ لَهُۥ طَلَبٗا","2181":"وَأُحِيطَ بِثَمَرِهِۦ فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُشۡرِكۡ بِرَبِّيٓ أَحَدٗا","2182":"وَلَمۡ تَكُن لَّهُۥ فِئَةٞ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا","2489":"وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ","2539":"وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ","2540":"فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ","2541":"قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ","2542":"قَالُواْ سَمِعۡنَا فَتٗى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ","2621":"وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ","2826":"فِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ","2827":"رِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ","3271":"وَجَآءَ رَجُلٞ مِّنۡ أَقۡصَا ٱلۡمَدِينَةِ يَسۡعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلۡمَلَأَ يَأۡتَمِرُونَ بِكَ لِيَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّي لَكَ مِنَ ٱلنَّٰصِحِينَ","3536":"مَّا جَعَلَ ٱللَّهُ لِرَجُلٖ مِّن قَلۡبَيۡنِ فِي جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ","3555":"مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا","3556":"لِّيَجۡزِيَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","3724":"وَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ رَجُلٞ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ","3725":"ٱتَّبِعُواْ مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرٗا وَهُم مُّهۡتَدُونَ","4086":"ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلٗا سَلَمٗا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ","4160":"وَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ وَإِن يَكُ كَٰذِبٗا فَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ مُسۡرِفٞ كَذَّابٞ","4161":"يَٰقَوۡمِ لَكُمُ ٱلۡمُلۡكُ ٱلۡيَوۡمَ ظَٰهِرِينَ فِي ٱلۡأَرۡضِ فَمَن يَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ إِن جَآءَنَاۚ قَالَ فِرۡعَوۡنُ مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ وَمَآ أَهۡدِيكُمۡ إِلَّا سَبِيلَ ٱلرَّشَادِ","4607":"هُمُ ٱلَّذِينَ كَفَرُواْ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَٱلۡهَدۡيَ مَعۡكُوفًا أَن يَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالٞ مُّؤۡمِنُونَ وَنِسَآءٞ مُّؤۡمِنَٰتٞ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِيبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَيۡرِ عِلۡمٖۖ لِّيُدۡخِلَ ٱللَّهُ فِي رَحۡمَتِهِۦ مَن يَشَآءُۚ لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابًا أَلِيمًا","5452":"وَأَنَّهُۥ كَانَ رِجَالٞ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقٗا"},"nay":46,"nq":53};
